import React from 'react';

// ─── Brand tokens ─────────────────────────────────────────────────────────────
const BLUE   = '#009FE3';
const NAVY   = '#003D6B';
const YELLOW = '#FFD100';

// ─── Types ───────────────────────────────────────────────────────────────────

export interface ParameterDef {
  /** Unique key used in state maps */
  id: string;
  /** Human-readable label shown on the card */
  label: string;
  /**
   * Must match the ThoughtSpot parameter name exactly (case-sensitive).
   * This is the name shown in the ThoughtSpot liveboard parameter panel.
   */
  parameterName: string;
  /** Selectable values — must match the parameter's allowed values in ThoughtSpot */
  options: { label: string; value: string }[];
  /** Default selected value (must be one of the options values) */
  defaultValue: string;
}

export type ParameterSelection = Record<string, string>;

interface ParameterBarProps {
  parameters: ParameterDef[];
  selected: ParameterSelection;
  onSelectionChange: (parameterId: string, value: string) => void;
  onResetAll: () => void;
}

// ─── Single parameter card ────────────────────────────────────────────────────

function ParameterCard({
  param,
  selected,
  onChange,
}: {
  param: ParameterDef;
  selected: string;
  onChange: (value: string) => void;
}) {
  const isDefault = selected === param.defaultValue;

  return (
    <div
      style={{
        width: 220,
        flexShrink: 0,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#FFFFFF',
        borderRadius: 10,
        border: `1.5px solid ${!isDefault ? YELLOW : 'rgba(0,0,0,0.09)'}`,
        boxShadow: !isDefault
          ? `0 0 0 3px rgba(255,209,0,0.18), 0 2px 8px rgba(0,0,0,0.06)`
          : '0 1px 4px rgba(0,0,0,0.06)',
        overflow: 'hidden',
        transition: 'border-color 0.15s ease, box-shadow 0.15s ease',
      }}
    >
      {/* ── Card header ── */}
      <div
        style={{
          padding: '9px 12px 8px',
          borderBottom: '1px solid rgba(0,0,0,0.07)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexShrink: 0,
          background: !isDefault
            ? `linear-gradient(135deg, rgba(255,209,0,0.12) 0%, rgba(255,209,0,0.04) 100%)`
            : '#FAFAFA',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {/* Sliders icon to distinguish from filter funnel */}
          <svg
            width="11"
            height="11"
            viewBox="0 0 24 24"
            fill="none"
            stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'}
            strokeWidth="2.5"
            strokeLinecap="round"
          >
            <line x1="4" y1="6" x2="20" y2="6" />
            <line x1="4" y1="12" x2="20" y2="12" />
            <line x1="4" y1="18" x2="20" y2="18" />
            <circle cx="9" cy="6" r="2" fill={!isDefault ? YELLOW : '#FFF'} stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'} strokeWidth="2" />
            <circle cx="15" cy="12" r="2" fill={!isDefault ? YELLOW : '#FFF'} stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'} strokeWidth="2" />
            <circle cx="9" cy="18" r="2" fill={!isDefault ? YELLOW : '#FFF'} stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'} strokeWidth="2" />
          </svg>
          <span
            style={{
              fontSize: 12,
              fontWeight: 700,
              color: !isDefault ? '#8B6914' : NAVY,
              letterSpacing: '-0.01em',
            }}
          >
            {param.label}
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
          {/* Currently selected value — shown as a badge */}
          <span
            style={{
              fontSize: 10,
              fontWeight: 700,
              color: !isDefault ? '#8B6914' : 'rgba(0,0,0,0.35)',
              backgroundColor: !isDefault ? YELLOW : 'rgba(0,0,0,0.06)',
              borderRadius: 5,
              padding: '2px 7px',
              letterSpacing: '0.01em',
              maxWidth: 90,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
            }}
          >
            {param.options.find((o) => o.value === selected)?.label ?? selected}
          </span>
          {/* Per-card reset button */}
          {!isDefault && (
            <button
              type="button"
              onClick={() => onChange(param.defaultValue)}
              title={`Reset to default (${param.defaultValue})`}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                padding: '1px 3px',
                color: 'rgba(0,0,0,0.35)',
                display: 'flex',
                alignItems: 'center',
              }}
            >
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
                <path d="M3 3v5h5" />
              </svg>
            </button>
          )}
        </div>
      </div>

      {/* ── Scrollable single-select option list ── */}
      <div
        style={{
          overflowY: 'auto',
          maxHeight: 172,
          padding: '3px 0',
          scrollbarWidth: 'thin',
          scrollbarColor: `rgba(255,209,0,0.4) transparent`,
        }}
      >
        {param.options.map((option) => {
          const isSelected = selected === option.value;
          return (
            <label
              key={option.value}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                padding: '6px 12px',
                cursor: 'pointer',
                backgroundColor: isSelected
                  ? 'rgba(255,209,0,0.12)'
                  : 'transparent',
                transition: 'background-color 0.10s ease',
                userSelect: 'none',
              }}
              onMouseEnter={(e) => {
                if (!isSelected)
                  (e.currentTarget as HTMLElement).style.backgroundColor =
                    'rgba(0,0,0,0.03)';
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLElement).style.backgroundColor =
                  isSelected ? 'rgba(255,209,0,0.12)' : 'transparent';
              }}
            >
              {/* Radio circle */}
              <span
                style={{
                  width: 15,
                  height: 15,
                  borderRadius: '50%',
                  flexShrink: 0,
                  border: `2px solid ${isSelected ? BLUE : 'rgba(0,0,0,0.22)'}`,
                  backgroundColor: '#FFFFFF',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: 'all 0.10s ease',
                }}
              >
                {isSelected && (
                  <span
                    style={{
                      width: 7,
                      height: 7,
                      borderRadius: '50%',
                      backgroundColor: BLUE,
                    }}
                  />
                )}
              </span>
              <input
                type="radio"
                name={param.id}
                value={option.value}
                checked={isSelected}
                onChange={() => onChange(option.value)}
                style={{ display: 'none' }}
              />
              <span
                style={{
                  fontSize: 12.5,
                  color: isSelected ? NAVY : '#2a2a2a',
                  fontWeight: isSelected ? 700 : 400,
                  letterSpacing: '-0.01em',
                  lineHeight: 1.3,
                  flex: 1,
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                }}
              >
                {option.label}
              </span>
              {isSelected && (
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="20 6 9 17 4 12" />
                </svg>
              )}
            </label>
          );
        })}
      </div>
    </div>
  );
}

// ─── Parameter bar ────────────────────────────────────────────────────────────

