          <svg
            width="13"
            height="13"
            viewBox="0 0 24 24"
            fill="none"
            stroke={NAVY}
            strokeWidth="2.2"
            strokeLinecap="round"
          >
            <line x1="4" y1="6" x2="20" y2="6" />
            <line x1="4" y1="12" x2="20" y2="12" />
            <line x1="4" y1="18" x2="20" y2="18" />
            <circle cx="9" cy="6" r="2.5" fill="white" stroke={NAVY} strokeWidth="2" />
            <circle cx="15" cy="12" r="2.5" fill="white" stroke={NAVY} strokeWidth="2" />
            <circle cx="9" cy="18" r="2.5" fill="white" stroke={NAVY} strokeWidth="2" />
          </svg>
          <span style={{ fontSize: 12, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>
            Parameters
          </span>
          {hasNonDefault && (
            <span
              style={{
                fontSize: 10,
                fontWeight: 700,
                backgroundColor: YELLOW,
                color: '#7A5C00',
                borderRadius: 10,
                padding: '1px 7px',
                letterSpacing: '0.02em',
              }}
