          {!hasNonDefault && (
            <span style={{ fontSize: 10, fontWeight: 500, color: 'rgba(0,0,0,0.35)', letterSpacing: '0.01em' }}>
              · changes what the dashboard calculates
            </span>
          )}
        </div>

        {hasNonDefault && (
          <button
            type="button"
            onClick={onResetAll}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              fontSize: 12,
              color: 'rgba(0,0,0,0.40)',
              fontWeight: 500,
              padding: 0,
              letterSpacing: '-0.01em',
              display: 'flex',
